<script setup>
import { computed, nextTick, ref, watch } from 'vue';
import documents from '../../../../docs/public/product-docs.json';
import { docLink } from '../portal-navigation.js';
const props = defineProps({ selection: { type: Object, required: true } });
function locationHref() { return window.location.href.split('?')[0]; }
const search = ref(''); const menu = ref(false); const copyStatus = ref('');
const current = computed(() => documents.find(item => item.id === props.selection.article));
const currentIndex = computed(() => documents.findIndex(item => item.id === props.selection.article));
const results = computed(() => { const query = search.value.trim().toLocaleLowerCase(); return documents.filter(item => `${item.title} ${item.summary} ${item.sections.map(s => s.body).join(' ')}`.toLocaleLowerCase().includes(query)); });
const categories = computed(() => [...new Set(results.value.map(item => item.category))]);
const previous = computed(() => documents[currentIndex.value - 1]); const next = computed(() => documents[currentIndex.value + 1]);
const sectionMissing = computed(() => Boolean(props.selection.section && !current.value?.sections.some((_, index) => `section-${index + 1}` === props.selection.section)));
function snippet(item) { const q = search.value.trim().toLocaleLowerCase(); const body = `${item.summary} ${item.sections.map(s => s.body).join(' ')}`; const start = Math.max(0, body.toLocaleLowerCase().indexOf(q) - 12); return `${start ? '…' : ''}${body.slice(start, start + 65)}…`; }
async function copy(value, label) { try { await navigator.clipboard.writeText(value); copyStatus.value = `${label}已复制`; } catch { copyStatus.value = '复制未完成，请手动选择文字或复制浏览器地址。'; } }
watch(() => [props.selection.article, props.selection.section], async () => {
  menu.value = false; copyStatus.value = ''; document.title = `${current.value?.title || '文档未找到'} · 元域文档`;
  await nextTick();
  const element = props.selection.section && document.getElementById(`doc-${props.selection.section}`);
  if (element) { element.scrollIntoView({ behavior: 'instant', block: 'start' }); element.focus({ preventScroll: true }); } else window.scrollTo(0, 0);
}, { immediate: true });
</script>

<template>
  <div class="docs-v2 v2-wrap">
    <aside class="docs-v2-sidebar"><a href="#/docs/overview" class="docs-brand">元域 <span>/ DOCS</span></a><label class="docs-search">搜索文档<input v-model="search" type="search" placeholder="搜索教程、架构或 API…"/></label><button class="docs-menu-toggle" :aria-expanded="menu" aria-controls="docs-categories" @click="menu = !menu">{{ menu ? '收起文档目录 −' : '展开文档目录 +' }}</button><nav id="docs-categories" :class="{ expanded: menu || search }" aria-label="文档目录"><div v-for="category in categories" :key="category"><h2>{{ category }}</h2><a v-for="item in results.filter(entry => entry.category === category)" :key="item.id" :href="docLink(item.id)" :aria-current="current?.id === item.id ? 'page' : undefined">{{ item.title }}<small v-if="search.trim()">{{ snippet(item) }}</small></a></div><p v-if="!results.length" class="docs-search-empty" role="status">没有找到匹配文档。试试“模型”“权限”或“订单”。</p></nav><div class="docs-sidebar-note">公开产品文档<br/>内部配置与业务数据不在此公开。</div></aside>
    <article v-if="current" class="docs-v2-article"><div class="docs-breadcrumb"><a href="#/docs/overview">文档</a><span>/</span>{{ current.category }}</div><h1>{{ current.title }}</h1><p class="docs-description">{{ current.summary }}</p><div class="docs-meta"><span>{{ current.updated || '2026-09-14' }}</span><span>{{ current.environment || '本地验证版' }}</span><button @click="copy(locationHref(), '文章链接')">复制文章链接 ↗</button></div><p v-if="sectionMissing" role="status" class="docs-inline-notice">链接中的章节不存在，已打开文章正文。</p><details class="docs-mobile-toc"><summary>本页目录</summary><a v-for="(section, index) in current.sections" :key="section.title" :href="docLink(current.id, `section-${index + 1}`)">{{ section.title }}</a></details><div class="docs-rule"/>
      <section v-for="(section, index) in current.sections" :id="`doc-section-${index + 1}`" :key="`${current.id}-${index}`" tabindex="-1"><h2><a :href="docLink(current.id, `section-${index + 1}`)">{{ section.title }} <span aria-hidden="true">#</span></a></h2><p>{{ section.body }}</p><ol v-if="section.steps"><li v-for="instruction in section.steps" :key="instruction">{{ instruction }}</li></ol><p v-if="section.expected" class="docs-expected"><b>预期结果</b>{{ section.expected }}</p><div v-if="section.code" class="docs-code"><div><span>示例</span><button @click="copy(section.code, '代码')">复制</button></div><pre><code>{{ section.code }}</code></pre></div></section>
      <div v-if="current.code" class="docs-code"><div><span>请求示例 · 不含真实凭证</span><button @click="copy(current.code, '代码')">复制</button></div><pre><code>{{ current.code }}</code></pre></div>
      <p class="docs-copy-status" role="status">{{ copyStatus }}</p><div class="docs-next-pages"><a v-if="previous" :href="docLink(previous.id)"><small>← 上一篇</small>{{ previous.title }}</a><a v-if="next" :href="docLink(next.id)"><small>下一篇 →</small>{{ next.title }}</a></div><div class="docs-help"><b>准备好验证了吗？</b><p>从合成资料开始，先检查模型与来源，再验证业务使用。</p><a href="#/demo">查看双 Agent 场景演示 →</a></div>
    </article>
    <article v-else class="docs-v2-article"><p class="v2-kicker">DOCUMENT NOT FOUND</p><h1>这篇文档不存在。</h1><p>链接可能有误，请从左侧目录选择文章。</p><a class="button secondary" href="#/docs/overview">返回文档首页</a></article>
    <aside v-if="current" class="docs-v2-toc"><span>本页目录</span><a v-for="(section, index) in current.sections" :key="section.title" :href="docLink(current.id, `section-${index + 1}`)" :aria-current="selection.section === `section-${index + 1}` ? 'location' : undefined">{{ section.title }}</a><div><span>相关入口</span><a href="#/demo">交互案例 ↗</a><a href="#/architecture">平台架构 ↗</a></div></aside>
  </div>
</template>

<style>
