padding:8px 0;display:inline-block}.docs-copy-status{font-size:12px;color:#326734;min-height:20px}.docs-inline-notice,.docs-search-empty{font-size:13px;color:#8a692c;line-height:1.9}.docs-mobile-toc,.docs-menu-toggle{display:none}
@media(max-width:1100px){.docs-v2{grid-template-columns:210px minmax(0,1fr);gap:35px}.docs-v2-toc{display:none}.docs-mobile-toc{display:block;border:1px solid #dce5d3;border-radius:5px;padding:14px;margin:25px 0;font-size:13px}.docs-mobile-toc summary{cursor:pointer}.docs-mobile-toc a{display:block;font-size:12px;color:#6a815d;padding:12px 0 0;line-height:1.7}.docs-v2-article h1{font-size:32px}}
